import { NextResponse } from "next/server";
import { PrismaClient } from "@prisma/client";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/app/api/auth/[...nextauth]/route";

const prisma = new PrismaClient();

export async function POST(request: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user || !session.user.id) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { pdfId, status, comment } = await request.json();

    if (!pdfId || !status || !comment) {
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400 }
      );
    }

    // Validate PDF exists
    const pdf = await prisma.pdf.findUnique({
      where: { id: pdfId },
    });

    if (!pdf) {
      return NextResponse.json(
        { error: "PDF not found" },
        { status: 404 }
      );
    }

    // Check if a review already exists for this PDF
    const existingReview = await prisma.pdf.findFirst({
      where: {
        id: pdfId,
        reviewText: { not: null },
      },
    });

    let review;
    if (existingReview) {
      // Update existing review
      review = await prisma.pdf.update({
        where: { id: pdfId },
        data: {
          reviewText: comment,
          status: status.toUpperCase(),
          reviewedAt: new Date(),
          reviewerId: session.user.id,
        },
      });
    } else {
      // Create new review
      review = await prisma.pdf.update({
        where: { id: pdfId },
        data: {
          reviewText: comment,
          status: status.toUpperCase(),
          reviewedAt: new Date(),
          reviewerId: session.user.id,
        },
      });
    }

    return NextResponse.json({
      success: true,
      review: {
        id: review.id,
        pdfId,
        reviewerId: session.user.id,
        status,
        comment,
        createdAt: review.reviewedAt,
      },
    });
  } catch (error) {
    console.error("Error in document-reviews POST:", error);
    return NextResponse.json(
      { error: "Failed to submit document review" },
      { status: 500 }
    );
  } finally {
    await prisma.$disconnect();
  }
}

export async function GET(request: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user || !session.user.id) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { searchParams } = new URL(request.url);
    const pdfId = searchParams.get("pdfId");

    if (!pdfId) {
      return NextResponse.json(
        { error: "Missing pdfId" },
        { status: 400 }
      );
    }

    // Fetch the document review
    const pdf = await prisma.pdf.findUnique({
      where: {
        id: pdfId,
        reviewText: { not: null },
      },
      select: {
        id: true,
        reviewText: true,
        status: true,
        reviewedAt: true,
        reviewerId: true,
      },
    });

    if (!pdf) {
      return NextResponse.json({
        success: true,
        review: null,
      });
    }

    return NextResponse.json({
      success: true,
      review: {
        id: pdf.id,
        pdfId,
        reviewerId: pdf.reviewerId,
        status: pdf.status.toLowerCase(),
        comment: pdf.reviewText,
        createdAt: pdf.reviewedAt,
      },
    });
  } catch (error) {
    console.error("Error in document-reviews GET:", error);
    return NextResponse.json(
      { error: "Failed to fetch document review" },
      { status: 500 }
    );
  } finally {
    await prisma.$disconnect();
  }
}